-- Deities and Demigods: Asgardian pantheon divine stat blocks, batch E.
-- Source: Deities and Demigods (2002), Chapter 6, pp. 192-199.
-- Printed 3.0 statistics remain source-of-truth; official 3.5 conversion deltas are recorded separately.

INSERT OR IGNORE INTO dnd35_sources
  (id,slug,name,abbreviation,publisher,system,edition,description,url,is_official,is_homebrew,owner_user_id)
VALUES ('dd-3.0','deities-and-demigods-3-0','Deities and Demigods','DD','Wizards of the Coast','dnd','3.0',
        'Deities and Demigods (2002): divine ranks, pantheons, salient divine abilities, divine minions, domains, spells, monsters, prestige classes, and ascension.',NULL,1,0,NULL);

UPDATE dnd35_deities SET symbol='Hammer' WHERE source_id='dd-3.0' AND slug='thor' AND owner_user_id IS NULL;
UPDATE dnd35_deities SET symbol='White double-bladed axe' WHERE source_id='dd-3.0' AND slug='thrym' AND owner_user_id IS NULL;
UPDATE dnd35_deities SET symbol='Sword' WHERE source_id='dd-3.0' AND slug='tyr' AND owner_user_id IS NULL;
UPDATE dnd35_deities SET symbol='Longbow' WHERE source_id='dd-3.0' AND slug='uller' AND owner_user_id IS NULL;

WITH desired(slug,name,page,description,mechanics) AS (VALUES
('dd-statblock-thor','Thor Divine Stat Block','192-194',
 'Thor is the divine-rank-18 greater Asgardian deity of storms, thunder, war, and the defense of Asgard.',
 '{"deitySlug":"thor","pantheon":"asgardian","sourceEdition":"3.0","rankBand":"greater","divineRank":18,"titles":["God of Thunder","Guardian of Asgard"],"symbol":"Hammer","homePlane":"Asgard","alignment":"CG","classes":[{"class":"Barbarian","level":20},{"class":"Ranger","level":20}],"sourceClassHitDieAnomaly":"The class header says Barbarian 20/Ranger 20, but the printed Hit Dice line labels the third 20d10 segment as Ftr. Preserve both statements; the official 3.5 ranger conversion is applied to the class-header Ranger levels rather than silently rewriting the source line.","creature":{"type":"Outsider","size":"Medium","hitDice":"20d8+220 outsider + 20d12+220 barbarian + 20d10+220 printed as Ftr despite Ranger 20 header","hitPoints":1260,"initiative":"+13, always first","speed":{"land":70},"armorClass":{"total":77,"dexterity":9,"divine":18,"natural":31,"deflection":9},"face":"5 ft. by 5 ft.","reachFeet":5},"attacks":{"mjolnirMelee":"+109/+104/+99/+94 melee","mjolnirRanged":"+104 ranged","mjolnirDamageMelee":"4d8+84/19-20/x3; greater deity maximum 116","mjolnirDamageRanged":"4d8+66/19-20/x3; greater deity maximum 98","greaterDeityAlways20OnAttacks":true,"greaterDeityMaximumDamage":true},"saves":{"fort":61,"ref":61,"will":59,"greaterDeityAlways20":true},"abilities":{"str":92,"dex":29,"con":32,"int":25,"wis":28,"cha":28},"specialQualities":{"printedDamageReduction":"71/+5 (4/-)","printedFireResistance":38,"spellResistance":50,"divineAura":{"radiusMiles":18,"dc":37},"printedFavoredEnemies":{"giants":5,"dragons":4,"goblinoids":3,"aberrations":2,"undead":1},"uncannyDodge":"cannot be flanked, +4 against traps","teleportWithoutErrorAtWill":true,"planeShiftAtWill":true,"sourceDuplicate":"The printed Special Qualities line repeats plane shift at will twice."},"salientDivineAbilities":["Alter Form","Alter Size","Annihilating Strike","Banestrike (giants)","Battlesense","Divine Celerity","Divine Rage","Divine Storm","Divine Weapon Focus (warhammer)","Divine Weapon Specialization (warhammer)","Energy Storm (electricity)","Extra Domain (Protection)","Extra Domain (Strength)","Extra Domain (War)","Hand of Death","Increased Damage Reduction","Indomitable Strength","Irresistible Blows","Power of Nature","Shapechange","Supreme Initiative","True Shapechange","Wound Enemy"],"domainPowers":{"chaosSpellsCasterLevelBonus":1,"goodSpellsCasterLevelBonus":1,"protectiveWardUsesPerDay":18,"protectiveWardResistanceBonus":18,"strengthFeatUsesPerDay":18,"strengthFeatBonus":18},"spellLikeAbilities":{"casterLevel":28,"chaosGoodCasterLevel":29,"saveDc":"37 + spell level"},"divineRage":{"usesPerDay":18,"duration":"1 hour or until ended","printedArmorClass":72,"printedHitPoints":1560,"printedAttack":"+114/+109/+104/+99 melee","printedDamage":"4d8+89/19-20/x3","printedFireResistance":60,"printedSpellResistance":48,"printedFort":66,"printedWill":64,"printedStr":102,"printedCon":42},"spellcasting":{"rangerSpellsPerDay":"6/5/5/5","rangerBaseDc":"19 + spell level"},"possessions":{"strengthBelt":"A magic belt doubles Thor''s Strength; its bonus is already included in the printed ability score.","chariot":"Foldable chariot drawn by Tanngrisnir and Tanngjost.","mjolnir":"+5 chaotic distance ghost touch holy mighty cleaving returning thundering warhammer; weighs about two tons and requires doubled Strength to wield; base damage 4d8. On a critical hit the target must save Fortitude DC 55 or become permanently deafened. A creature attempting to hold it without Thor''s special gauntlets takes 4d8 temporary Constitution damage each round."},"companions":["Tanngrisnir and Tanngjost, legendary chariot goats"],"portfolioSense":"All storms, combat of any kind, and any Aesir cry for aid in battle; instantaneously and nineteen weeks into the past and future.","sourcePortfolioAnomaly":"The printed portfolio-sense horizon is nineteen weeks even though Thor is divine rank 18.","automaticActions":{"skills":["Animal Empathy","Climb","Concentration","Craft (metalworking)","Craft (stoneworking)","Handle Animal","Heal","Hide","Intimidate","Intuit Direction","Jump","Knowledge (nature)","Listen","Move Silently","Ride (horse)","Search","Spot","Swim","Use Rope","Wilderness Lore"],"freeActionDcMaximum":30,"maximumPerRound":20},"createMagicItems":"Any kind of magic item related to combat or controlling the weather.","avatarStatus":"No Avatar salient divine ability is present in the printed stat block; no avatar stat block is created.","revision3_5":{"alignmentSubtypes":["chaotic","good"],"baseDamageReduction":"30/epic","damageReductionWithIncreasedDamageReduction":"35/epic and lawful","fireResistance":23,"additionalOutsiderSkillPoints":true,"rangerInterpretation":"Because the class header identifies Ranger 20 while the HD line says Ftr, apply the official ranger conversion to those 20 class levels but preserve the printed Ftr label as a source contradiction.","ranger":{"hitDice":"20d8 instead of 20d10","convertedHitPoints":1220,"additionalSkillPoints":40,"wildEmpathy":true,"favoredEnemyBonusTotal":18,"favoredEnemyDistributionNote":"The official update gives only the total +18 under revised ranger rules; do not invent a replacement per-enemy distribution.","combatStyle":"Recalculate using revised ranger combat-style feats.","bonusAndClassFeatures":["Endurance","woodland stride","swift tracker","evasion","camouflage","hide in plain sight"]},"barbarian":{"trapSenseIncrease":2,"classDamageReduction":"5/- instead of 4/-","mightyRageNote":"Divine Rage replaces ordinary mighty rage for Thor.","indomitableWillBonusAgainstEnchantmentWhileRaging":4},"battlesense":"Replaces uncanny dodge and improved uncanny dodge.","divineCelerity":"Uses revised haste.","divineRage":"Instead of an extra partial action each round, revised Divine Rage grants one extra attack at full attack bonus whenever Thor uses the full attack action.","increasedDamageReduction":"Adds 5 to rank-based DR and an opposed-alignment bypass; chaotic-good Thor therefore uses lawful as the opposed alignment.","irresistibleBlows":"Warhammer attacks count as adamantine for overcoming DR and hardness.","strengthDomain":"Replace endure elements with enlarge person.","weatherDomain":"Replace ice storm with call lightning storm.","defunctSkills":["Animal Empathy -> wild empathy","Intuit Direction migrated","Wilderness Lore -> Survival"],"defunctFeat":"Improved Sunder is replaced by revised Improved Sunder where relevant."}}'),

('dd-statblock-thrym','Thrym Divine Stat Block','194-195',
 'Thrym is the divine-rank-14 intermediate Asgardian lord of the frost giants and deity of war, cold, and giants.',
 '{"deitySlug":"thrym","pantheon":"asgardian","sourceEdition":"3.0","rankBand":"intermediate","divineRank":14,"titles":["Lord of the Frost Giants"],"symbol":"White double-bladed axe","homePlane":"Midgard (Jotunheim)","alignment":"CE","classes":[{"class":"Barbarian","level":20},{"class":"Fighter","level":20}],"creature":{"type":"Outsider","sourceSubtypes":["Chaotic","Cold","Evil"],"size":"Gargantuan","hitDice":"20d8+200 outsider + 20d12+200 barbarian + 20d10+200 fighter","hitPoints":1200,"initiative":12,"speed":{"land":130},"armorClass":{"total":63,"size":-4,"dexterity":8,"divine":14,"natural":27,"deflection":8},"face":"20 ft. by 20 ft.","reachFeet":20},"attacks":{"greataxe":"+77/+72/+67/+62 melee, Gargantuan +5 chaotic icy burst mighty cleaving greataxe","greataxeDamage":"4d6+34/19-20/x3"},"saves":{"fort":56,"ref":56,"will":57},"abilities":{"str":44,"dex":27,"con":31,"int":27,"wis":28,"cha":27},"specialQualities":{"printedDamageReduction":"49/+4 (4/-)","fireImmunity":true,"fastHealing":34,"coldSubtype":true,"spellResistance":46,"divineAura":{"radiusFeet":1400,"dc":32},"uncannyDodge":"cannot be flanked, +4 against traps","teleportWithoutErrorAtWill":true,"planeShiftAtWill":true},"salientDivineAbilities":["Alter Form","Alter Size","Banestrike (good outsiders)","Battlesense","Call Creatures (frost giants)","Divine Battle Mastery","Divine Fast Healing","Divine Rage","Divine Storm","Energy Storm (cold)","Extra Domain (Strength)","Extra Domain (War)","Extra Energy Immunity (fire)","Indomitable Strength","Irresistible Blows","Shapechange","Sunder and Disjoin"],"domainPowers":{"chaosSpellsCasterLevelBonus":1,"earthTurningUsesPerDay":14,"evilSpellsCasterLevelBonus":1,"strengthFeatUsesPerDay":14,"strengthFeatBonus":14},"spellLikeAbilities":{"casterLevel":24,"chaosEvilCasterLevel":25,"saveDc":"32 + spell level"},"divineRage":{"usesPerDay":14,"duration":"1 hour or until ended","printedArmorClass":58,"printedHitPoints":1500,"printedAttack":"+82/+77/+72/+67 melee","printedDamage":"4d6+39/19-20/x3","printedSpellResistance":56,"printedFort":61,"printedWill":62,"printedStr":54,"printedCon":41},"portfolioSense":"Events involving giants, snow, or sleet, instantaneously and fourteen weeks into the past.","automaticActions":{"skills":["Craft (stoneworking)","Disguise","Profession (stonemason)"],"freeActionDcMaximum":25,"maximumPerRound":10},"createMagicItems":{"scope":"magic weapons or armor, wondrous items related to stoneworking, and items that produce or use cold or ice","maximumMarketPriceGp":200000},"avatarStatus":"No Avatar salient divine ability is present in the printed stat block; no avatar stat block is created.","revision3_5":{"alignmentSubtypes":["chaotic","evil"],"elementalSubtypes":["cold"],"damageReduction":"25/epic","fireImmunityFromSalientAbility":true,"additionalOutsiderSkillPoints":true,"coldSubtype":"Use revised Monster Manual cold-subtype and vulnerability rules rather than silently retaining the 3.0 subtype text.","barbarian":{"trapSenseIncrease":2,"classDamageReduction":"5/- instead of 4/-","mightyRageNote":"Divine Rage replaces ordinary mighty rage for Thrym.","indomitableWillBonusAgainstEnchantmentWhileRaging":4},"fighter":"No class-feature change in the official revision.","battlesense":"Replaces uncanny dodge and improved uncanny dodge.","divineRage":"Instead of an extra partial action each round, revised Divine Rage grants one extra attack at full attack bonus whenever Thrym uses the full attack action.","irresistibleBlows":"Greataxe attacks count as adamantine for overcoming DR and hardness.","strengthDomain":"Replace endure elements with enlarge person.","defunctSkills":["Wilderness Lore -> Survival"],"defunctFeat":"Improved Sunder is replaced by revised Improved Sunder; choose a replacement if both printed Sunder and Improved Sunder would duplicate under 3.5."}}'),

('dd-statblock-tyr','Tyr Divine Stat Block','195-197',
 'Tyr is the divine-rank-15 intermediate Asgardian deity of courage, trust, strategy, tactics, and writing.',
 '{"deitySlug":"tyr","pantheon":"asgardian","sourceEdition":"3.0","rankBand":"intermediate","divineRank":15,"titles":["God of Courage and Strategy"],"symbol":"Sword","homePlane":"Asgard","alignment":"LN","classes":[{"class":"Cleric","level":20},{"class":"Fighter","level":20}],"creature":{"type":"Outsider","size":"Medium","hitDice":"20d8+180 outsider + 20d8+180 cleric + 20d10+180 fighter","hitPoints":1060,"initiative":12,"speed":{"land":60},"armorClass":{"total":69,"dexterity":8,"divine":15,"natural":28,"deflection":8},"face":"5 ft. by 5 ft.","reachFeet":5},"attacks":{"longsword":"+76/+71/+66/+61 melee, +5 bane keen lawful longsword","longswordVsEvilOutsiders":"+78/+73/+68/+63 melee","longswordDamage":"1d8+35/15-20","longswordDamageVsEvilOutsiders":"2d6 plus 1d8+35/15-20","spellTouch":{"melee":66,"ranged":63}},"saves":{"fort":58,"ref":57,"will":58},"abilities":{"str":32,"dex":27,"con":28,"int":43,"wis":28,"cha":27},"specialAttacks":{"turnUndeadPerDay":19},"specialQualities":{"printedDamageReduction":"50/+4","printedFireResistance":35,"printedSonicResistance":35,"spellResistance":67,"divineAura":{"radiusFeet":1500,"dc":32},"teleportWithoutErrorAtWill":true,"planeShiftAtWill":true},"salientDivineAbilities":["Alter Form","Alter Size","Annihilating Strike","Banestrike (giants)","Banestrike (evil outsiders)","Battlesense","Create Greater Object","Create Object","Divine Battle Mastery","Divine Inspiration (courage)","Divine Storm","Divine Weapon Focus (longsword)","Divine Weapon Specialization (longsword)","Increased Energy Resistance (sonic)","Increased Spell Resistance","Lay Quest","Power of Truth","Shapechange"],"domainPowers":{"lawSpellsCasterLevelBonus":1,"protectiveWardUsesPerDay":15,"protectiveWardResistanceBonus":20},"spellLikeAbilities":{"casterLevel":25,"lawCasterLevel":26,"saveDc":"33 + spell level"},"spellcasting":{"clericSpellsPerDay":"6/9/8/8/8/8/6/6/6/6","clericBaseDc":"19 + spell level"},"portfolioSense":"Events related to planning, preparing, and training for battle; any battle; and any courageous choice or decision regardless of number involved, in the present and fifteen weeks into the past.","automaticActions":{"skills":["Diplomacy","Gather Information","Knowledge (arcana)","Knowledge (history)","Knowledge (nobility and royalty)","Knowledge (the planes)","Knowledge (religion)","Sense Motive"],"freeActionDcMaximum":25,"maximumPerRound":10},"createMagicItems":{"scope":"items providing morale bonuses plus any magic weapon or armor","maximumMarketPriceGp":200000},"avatarStatus":"No Avatar salient divine ability is present in the printed stat block; no avatar stat block is created.","revision3_5":{"alignmentSubtypes":["lawful"],"damageReduction":"25/epic","fireResistance":20,"additionalOutsiderSkillPoints":true,"cleric":"No class-feature change in the official revision.","fighter":"No class-feature change in the official revision.","battlesense":"Replaces uncanny dodge and improved uncanny dodge if gained from another source.","increasedEnergyResistanceSonic":"Recalculate under the revised Increased Energy Resistance ability rather than treating the printed 35 as authoritative 3.5 resistance.","increasedSpellResistance":"The printed SR 67 remains consistent with normal deity SR 47 plus the ability''s +20 increase.","divineInspiration":"Use the official revised Divine Inspiration effect appropriate to courage rather than silently preserving obsolete 3.0 wording.","defunctSkills":["Innuendo ranks reassigned","Scry ranks reassigned"],"defunctFeat":"Improved Sunder is replaced by revised Improved Sunder; choose a replacement if a duplicate results."}}'),

('dd-statblock-uller','Uller Divine Stat Block','197-199',
 'Uller is the divine-rank-6 lesser Asgardian deity of archers, hunting, winter, skiing, and wilderness balance.',
 '{"deitySlug":"uller","pantheon":"asgardian","sourceEdition":"3.0","rankBand":"lesser","divineRank":6,"titles":["God of Hunting, Archery, and Winter"],"symbol":"Longbow","homePlane":"Asgard","alignment":"CN","classes":[{"class":"Barbarian","level":20},{"class":"Ranger","level":20}],"creature":{"type":"Outsider","size":"Medium","hitDice":"20d8+160 outsider + 20d12+160 barbarian + 20d10+160 ranger","hitPoints":1080,"initiative":20,"speed":{"land":70},"armorClass":{"total":59,"dexterity":16,"divine":6,"natural":19,"deflection":8},"face":"5 ft. by 5 ft.","reachFeet":5},"attacks":{"greatsword":"+61/+56/+51/+46 melee, +5 bane frost brand greatsword","greatswordVsFavoredEnemy":"+63/+58/+53/+48 melee","longbow":"+73/+68/+63/+58 ranged, +5 bane mighty chaotic icy burst composite longbow (+10 Str) with +5 arrows","longbowVsFavoredEnemy":"+75/+70/+65/+60 ranged","greatswordDamage":"2d6+20/19-20","longbowDamage":"1d8+20/19-20/x3","favoredEnemyExtraDamage":"+2d6"},"saves":{"fort":46,"ref":54,"will":46},"abilities":{"str":30,"dex":42,"con":26,"int":25,"wis":27,"cha":26},"specialQualities":{"printedDamageReduction":"41/+4 (4/-)","printedFireResistance":26,"spellResistance":38,"divineAura":{"radiusFeet":600,"dc":24},"printedFavoredEnemies":{"dragons":5,"magicalBeasts":4,"goblinoids":3,"aberrations":2,"undead":1},"greaterRageUsesPerDay":6,"uncannyDodge":"cannot be flanked, +4 against traps","teleportWithoutErrorAtWill":true,"planeShiftAtWill":true},"salientDivineAbilities":["Alter Form","Alter Size","Divine Archery","Divine Celerity","Divine Ranger","Icewalking","Instant Move","Shift Form"],"uniqueAbilities":{"icewalking":"Uller can glide through or over snow and ice as easily as a fish swims through water, leaving no track, tunnel, hole, ripple, or other sign of passage."},"domainPowers":{"chaosSpellsCasterLevelBonus":1,"protectiveWardUsesPerDay":6,"protectiveWardResistanceBonus":6,"freedomOfMovementRoundsPerDay":6},"spellLikeAbilities":{"casterLevel":16,"chaosCasterLevel":17,"saveDc":"24 + spell level"},"greaterRage":{"printedArmorClass":57,"printedHitPoints":1260,"printedAttack":"+64/+59/+54/+49 melee","printedDamage":"2d6+23/19-20","printedFort":49,"printedWill":49,"printedStr":36,"printedCon":32,"durationRounds":14,"notWindedAfterward":true},"spellcasting":{"rangerSpellsPerDay":"5/5/5/5","rangerBaseDc":"18 + spell level"},"portfolioSense":"Efforts to feed 500 or more people through hunting, and archery contests whose spectators and contestants total at least 500 people.","automaticActions":{"skills":["Animal Empathy","Craft (bowmaking)","Hide","Intuit Direction","Move Silently","Wilderness Lore"],"freeActionDcMaximum":20,"maximumPerRound":5},"createMagicItems":{"scope":"any magic item related to hunting or archery","maximumMarketPriceGp":30000},"avatarStatus":"No Avatar salient divine ability is present in the printed stat block; no avatar stat block is created.","revision3_5":{"alignmentSubtypes":["chaotic"],"damageReduction":"20/epic","fireResistance":11,"additionalOutsiderSkillPoints":true,"ranger":{"hitDice":"20d8 instead of 20d10","convertedHitPoints":1040,"additionalSkillPoints":40,"wildEmpathy":true,"favoredEnemyBonusTotal":18,"favoredEnemyDistributionNote":"The official update gives only the total +18 under revised ranger rules; do not invent a replacement per-enemy distribution.","combatStyle":"Recalculate using revised ranger combat-style feats.","bonusAndClassFeatures":["Endurance","woodland stride","swift tracker","evasion","camouflage","hide in plain sight"]},"barbarian":{"trapSenseIncrease":2,"classDamageReduction":"5/- instead of 4/-","mightyRage":"Because Uller lacks Divine Rage, apply revised 20th-level mighty rage: +2 additional Strength and Constitution and +1 Will compared with the old greater-rage values.","indomitableWillBonusAgainstEnchantmentWhileRaging":4},"divineCelerity":"Uses revised haste.","divineRanger":"Apply Divine Ranger bane and tracking benefits to the revised favored-enemy framework.","travelDomain":"Replace expeditious retreat with longstrider and rename teleport without error to greater teleport.","defunctSkills":["Animal Empathy -> wild empathy","Intuit Direction migrated","Wilderness Lore -> Survival"]}}')
)
INSERT INTO dnd35_rules
  (id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,
   category,kind,is_variant,default_enabled,parent_slug,supersedes_slug,tags,mechanics)
SELECT
  'dd-rule-'||d.slug,'dd-3.0',d.page,d.slug,d.name,d.description,
  'Use the structured mechanics payload for the printed Deities and Demigods divine stat block. Printed 3.0 values remain source-of-truth; revision3_5 records official conversion deltas.',
  0,NULL,1,'deity','divine-stat-block',0,1,'dd-asgardian-pantheon',NULL,
  '["deities-and-demigods","asgardian","deity-stat-block","revision-3.5"]',
  d.mechanics
FROM desired d
WHERE NOT EXISTS (
  SELECT 1 FROM dnd35_rules r WHERE r.source_id='dd-3.0' AND r.slug=d.slug AND r.owner_user_id IS NULL
);